<script setup lang="ts">

import { GoogleMap, CustomMarker } from 'vue3-google-map'

import type { Clinic } from '~/types/types';

const props = defineProps({
    positions: {
        type: Object as () => Clinic[] | { lat: string, long: string }[] | null,
        required: true
    },
    center: {
        type: Object as () => { lat: number, lng: number },
        default: { lat: 40.859995453917276, lng: -73.95794147644851 }
    },
    zoom: {
        type: Number,
        default: 9.5
    }
})

const config = useRuntimeConfig()
const google_api_key = config.public.googleApiKey as string;

const mapStyles = [
    // base: near-white land, no text labels anywhere
    { elementType: "geometry", stylers: [{ color: "#eaf4fb" }] },
    { elementType: "labels", stylers: [{ visibility: "off" }] },
    { featureType: "poi", stylers: [{ visibility: "off" }] },
    { featureType: "transit", stylers: [{ visibility: "off" }] },
    { featureType: "administrative", elementType: "geometry", stylers: [{ visibility: "off" }] },

    // water: pale blue fill
    { featureType: "water", elementType: "geometry", stylers: [{ color: "#cfe8f6" }] },
    { featureType: "landscape", elementType: "geometry", stylers: [{ color: "#eaf4fb" }] },

    // roads: light grid lines that get darker/bolder up the road hierarchy
    { featureType: "road", elementType: "geometry", stylers: [{ color: "#bcdcee" }] },
    { featureType: "road", elementType: "geometry.stroke", stylers: [{ visibility: "off" }] },
    { featureType: "road.arterial", elementType: "geometry", stylers: [{ color: "#5ba3d0" }] },
    { featureType: "road.highway", elementType: "geometry", stylers: [{ color: "#1b4f72" }] },
    { featureType: "road.highway", elementType: "geometry.stroke", stylers: [{ color: "#153e5c" }, { weight: 0.5 }] },
];

</script>

<template>

    <ClientOnly>
        <GoogleMap :api-key="google_api_key" style="width: 100%; height: 100%" :center="props.center"
            :styles="mapStyles" :zoom="props.zoom" :libraries="['marker']">

            <template v-for="(location, index) in props.positions" :key="index">
                <CustomMarker :options="{ position: { lat: Number(location.lat), lng: Number(location.long) }, anchorPoint: 'BOTTOM_CENTER' }">
                    <div class="custom-marker">
                        <svg width="47" height="67" viewBox="0 0 64 89" fill="none" xmlns="http://www.w3.org/2000/svg"
                            xmlns:xlink="http://www.w3.org/1999/xlink">
                            <rect y="11.4188" width="44.1191" height="79.4144" transform="rotate(-15 0 11.4188)"
                                fill="url(#pattern0_20_142)" />
                            <defs>
                                <pattern id="pattern0_20_142" patternContentUnits="objectBoundingBox" width="1"
                                    height="1">
                                    <use xlink:href="#image0_20_142"
                                        transform="matrix(0.00916182 0 0 0.00510828 -5.99508 -1.55033)" />
                                </pattern>
                                <image id="image0_20_142" width="868" height="868" preserveAspectRatio="none"
                                    xlink:href="data:image/png;base64," />
                            </defs>
                        </svg>

                    </div>

                    <!-- i -->
                </CustomMarker>
            </template>
        </GoogleMap>
    </ClientOnly>

</template>

<style>
.custom-marker {
    display: block;
    width: 64px;
    height: 89px;
    box-sizing: border-box;
}
</style>
